import{_ as e,o as l,c as r,a0 as t}from"./chunks/framework.DqMqoJl9.js";const p=JSON.parse('{"title":"懒加载与预加载","description":"","frontmatter":{},"headers":[],"relativePath":"performance/old/3_load.md","filePath":"performance/old/3_load.md","lastUpdated":1791573371000}'),o={name:"performance/old/3_load.md"};function i(d,a,n,s,h,_){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="懒加载与预加载" tabindex="-1">懒加载与预加载 <a class="header-anchor" href="#懒加载与预加载" aria-label="Permalink to &quot;懒加载与预加载&quot;">​</a></h1><h2 id="_1-懒加载" tabindex="-1">1 懒加载 <a class="header-anchor" href="#_1-懒加载" aria-label="Permalink to &quot;1 懒加载&quot;">​</a></h2><p>懒加载也叫延迟加载，指的是在长网页中延迟加载图像，是一种很好优化网页性能的方式。用户滚动到它们之前，可视区域外的图像不会加载。这与图像预加载相反，在长网页上使用延迟加载将使网页加载更快。在某些情况下，它还可以帮助减少服务器负载。常适用图片很多，页面很长的电商网站场景中。</p><h3 id="_1-1-为什么要使用懒加载" tabindex="-1">1.1 为什么要使用懒加载 <a class="header-anchor" href="#_1-1-为什么要使用懒加载" aria-label="Permalink to &quot;1.1 为什么要使用懒加载&quot;">​</a></h3><ul><li>能提升用户的体验，例如用户打开像手机淘宝长页面的时候，如果页面上所有的图片都需要加载，由于图片数目较大，等待时间就会很长，这就严重影响用户体验</li><li>减少无效资源的加载，这样能明显减少了服务器的压力和流量，也能够减小浏览器的负担</li><li>防止并发加载的资源过多会阻塞 js 的加载，影响网站的正常使用</li></ul><h3 id="_1-2-实现原理" tabindex="-1">1.2 实现原理 <a class="header-anchor" href="#_1-2-实现原理" aria-label="Permalink to &quot;1.2 实现原理&quot;">​</a></h3><p>首先将页面上的图片的 src 属性设为空字符串，而图片的真实路径则设置在 data-src 属性中。</p><p>当页面滚动的时候需要去监听 scroll 事件，在 scroll 事件的回调中，判断我们的懒加载的图片是否进入可视区域,如果图片在可视区内将图片的 src 属性设置为 data-src 的值，这样就可以实现延迟加载</p><h2 id="_2-预加载" tabindex="-1">2 预加载 <a class="header-anchor" href="#_2-预加载" aria-label="Permalink to &quot;2 预加载&quot;">​</a></h2><p>资源预加载是另一个性能优化技术，我们可以使用该技术来预先告知浏览器某些资源可能在将来会被使用到。</p><p>预加载简单来说就是将所有所需的资源提前请求加载到本地，这样后面在需要用到时就直接从缓存取资源</p><h3 id="_2-1-为什么要使用预加载" tabindex="-1">2.1 为什么要使用预加载 <a class="header-anchor" href="#_2-1-为什么要使用预加载" aria-label="Permalink to &quot;2.1 为什么要使用预加载&quot;">​</a></h3><p>在网页全部加载之前，对一些主要内容进行加载，以提供给用户更好的体验。</p><p>通常适用于交互比较多的页面或者游戏。比如页面一部分需要用户的交互才会出现，如果没有用预加载的话，后续出现的内容或者交互的音效就会因为没有加载完成而不会及时的出现，那么体验就会很差。</p><h3 id="_2-2-实现方法" tabindex="-1">2.2 实现方法 <a class="header-anchor" href="#_2-2-实现方法" aria-label="Permalink to &quot;2.2 实现方法&quot;">​</a></h3><ul><li>html 标签</li><li>image 对象</li><li>ajax，可以更精细的控制加载过程</li><li>preloadJS 库</li></ul>',16)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
